return items.map(item => {
  let inputText = item.json.output;

  // 1. Convertir entidades HTML primero
  let cleanedText = inputText
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');

  // 2. Eliminar barras invertidas de escape
  cleanedText = cleanedText.replace(/\\"/g, '"');

  // 3. Limpieza de Markdown y otros caracteres no deseados
  cleanedText = cleanedText
    .replace(/\*\*/g, '')      // Elimina negrita (**)
    .replace(/#/g, '')         // Elimina encabezados (#)
    .replace(/_/g, '')         // Elimina cursiva (_)
    .replace(/`/g, '');        // Elimina código en línea (`)

  // 4. Normalizar los saltos de línea
  cleanedText = cleanedText.replace(/\n+/g, ' ');

  // 5. Normalizar espacios múltiples a un solo espacio
  cleanedText = cleanedText.replace(/\s+/g, ' ');

  // 6. Eliminar espacios al inicio y final
  cleanedText = cleanedText.trim();

  // 7. Asignar el texto limpio y seguro a la nueva propiedad
  item.json.cleanedTextForTTS = cleanedText;

  return item;
});

// Accedemos a la lista de noticias anidada
const items = $input.item.json.rss.channel.item;

// Creamos una nueva lista con el formato correcto
const formattedItems = items.map(item => {

  // Tomamos el contenido HTML y lo guardamos en una variable
  const htmlContent = item['content:encoded'] || '';

  // Usamos una expresión regular para eliminar todas las etiquetas HTML
  // y .trim() para quitar espacios en blanco al principio o al final.
  const plainTextContent = htmlContent.replace(/<[^>]*>/g, '').trim();

  return {
    title: item.title,
    link: item.link,
    pubDate: item.pubDate,
    creator: item['dc:creator'],
    content: plainTextContent // Usamos el texto ya limpio
  };
});

// Devolvemos la nueva lista formateada
return formattedItems;

// Array para guardar todas las noticias
let allHistoricalNews = [];

// Obtener los datos de entrada
const rawData = items[0]?.json?.propertyName;

// Comprobar si hay datos para procesar
if (rawData && Array.isArray(rawData) && rawData.length > 0) {
    // Recorrer cada elemento de la lista de entrada
    for (const jsonString of rawData) {
        try {
            const parsedData = JSON.parse(jsonString);

            // Si el elemento es un array, añadir todos sus objetos
            if (Array.isArray(parsedData)) {
                allHistoricalNews = allHistoricalNews.concat(parsedData);
            } else {
            // Si es un solo objeto, añadirlo directamente
                allHistoricalNews.push(parsedData);
            }
        } catch (e) {
            console.error("Error al procesar un elemento del historial: ", jsonString, e);
        }
    }
}

// Si al final no hay noticias, devolver un resultado vacío
if (allHistoricalNews.length === 0) {
    return [{ json: { historial: [] } }];
}

// Obtener la fecha de hace 7 días (hoy es 24 de septiembre de 2025)
const sevenDaysAgo = $now.minus({ days: 7 }).toFormat('yyyy-MM-dd'); // Esto dará '2025-09-17'

// Filtrar las noticias para incluir solo las de la última semana
const filteredHistoricalNews = allHistoricalNews.filter(article => {
    return article && article.pubDate && article.pubDate >= sevenDaysAgo;
});

// Devolver solo el título y la fecha de las noticias filtradas
const cleanedHistory = filteredHistoricalNews.map(article => ({
    title: article.title,
    pubDate: article.pubDate
}));

// Devolver el resultado final
return [{
    json: {
        historial: cleanedHistory
    }
}];

