// Función para calcular similitud entre dos strings
function calculateSimilarity(str1, str2) {
  if (!str1 || !str2) return 0;

  const longer = str1.length > str2.length ? str1 : str2;
  const shorter = str1.length > str2.length ? str2 : str1;

  if (longer.length === 0) return 1.0;

  const editDistance = getEditDistance(longer, shorter);
  return (longer.length - editDistance) / longer.length;
}

// Función para calcular la distancia de Levenshtein
function getEditDistance(str1, str2) {
  const matrix = [];

  for (let i = 0; i <= str2.length; i++) {
    matrix[i] = [i];
  }

  for (let j = 0; j <= str1.length; j++) {
    matrix[0][j] = j;
  }

  for (let i = 1; i <= str2.length; i++) {
    for (let j = 1; j <= str1.length; j++) {
      if (str2.charAt(i - 1) === str1.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1,
          matrix[i][j - 1] + 1,
          matrix[i - 1][j] + 1
        );
      }
    }
  }

  return matrix[str2.length][str1.length];
}

// Función para encontrar un enlace similar existente
function findSimilarLink(targetLink, existingLinks, threshold = 0.85) {
  for (const [existingLink, data] of existingLinks) {
    const similarity = calculateSimilarity(targetLink, existingLink);
    if (similarity >= threshold) {
      return existingLink;
    }
  }
  return null;
}

const inputData = items[0]?.json || {};

// Crear un mapa para fusionar los datos usando enlaces como clave.
const newsMap = new Map();

// 1. Procesar la lista de resúmenes (data) primero para tener una base.
const summaries = inputData.data || [];
for (const item of summaries) {
  const link = item?.output?.link;
  const summary = item?.output?.summary;

  if (link && summary) {
    newsMap.set(link, {
      title: null,
      summary: summary
    });
  }
}

// 2. Procesar la lista de títulos (top_15_news) y correlacionar por similitud.
const titles = inputData.output?.top_15_news || [];
for (const item of titles) {
  const link = item?.link;
  const title = item?.title;

  if (link && title) {
    // Primero intentamos encontrar una coincidencia exacta
    if (newsMap.has(link)) {
      const existingNews = newsMap.get(link);
      existingNews.title = title;
    } else {
      // Si no hay coincidencia exacta, buscamos enlaces similares
      const similarLink = findSimilarLink(link, newsMap);

      if (similarLink) {
        // Actualizamos la entrada existente con el título
        const existingNews = newsMap.get(similarLink);
        existingNews.title = title;
      } else {
        // Si no hay enlace similar, creamos una nueva entrada
        newsMap.set(link, {
          title: title,
          summary: null
        });
      }
    }
  }
}

// Convertir el mapa a un array de objetos para el output final.
const todayNews = Array.from(newsMap.values());

// Procesar el historial de noticias sin cambios.
const historicalNews = (inputData.historial || []).map(item => ({
  title: item.title,
  pubDate: item.pubDate
}));

// Devolver el objeto final con los datos combinados.
return [{
  json: {
    today_news: todayNews,
    historical_news: historicalNews
  }
}];

